BEGIN;
-- Acquire an exclusive row lock on the inventory row.
SELECT quantity FROM inventory WHERE product_id = 42 FOR UPDATE;
-- Any concurrent transaction running the same statement now BLOCKS here.

-- Safe to read-modify-write because we hold the lock:
UPDATE inventory SET quantity = quantity - 1 WHERE product_id = 42;
COMMIT;  -- lock released; the blocked transaction now proceeds and sees the new value
